foreach(['AdminAuth','Pricing','Products','Inventory','Vouchers','Orders','PartnerCredit'] as $c)require_once dirname(__DIR__).'/src/'.$c.'.php';$db=new PDO(getenv('JINGO_TEST_DSN').';dbname='.$argv[1],getenv('JINGO_TEST_USER')?:'root',getenv('JINGO_TEST_PASSWORD')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$db->exec("SET time_zone='+00:00'");[$mode,$id,$body,$partner]=json_decode(base64_decode($argv[2],true),true,512,JSON_THROW_ON_ERROR);try{$service=new PartnerCredit($db);if($mode==='charge')$service->charge($id,$body,'spoof',$partner);elseif($mode==='repay')$service->repay($id,$body,'admin');else exit(1);echo 'saved';}catch(HttpError $e){if(!in_array($e->status,[400,409],true))throw $e;echo $e->status===400?'invalid':'conflict';}
